export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const service = new CustomerService();
  const repository = new CustomerRepository();
  const erasures = new ErasureService();
  app.get('/health', async () => ({ status: 'ok', service: 'customer-service' }));
  app.post('/v1/customers/:customerId/erasure-requests', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { customerId } = z.object({ customerId: z.string().uuid() }).parse(request.params);
    const key = request.headers['idempotency-key'];
    if (typeof key !== 'string' || key.length < 8 || key.length > 200) {
      return reply.code(400).send({ error: 'valid_idempotency_key_required' });
    }
    const erasure = await erasures.request(principal.merchantId, customerId, key);
    return erasure ? reply.code(202).send(erasure) : reply.code(404).send({ error: 'customer_not_found' });
  });
  app.get('/v1/erasure-requests/:requestId', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { requestId } = z.object({ requestId: z.string().uuid() }).parse(request.params);
    const erasure = await erasures.find(principal.merchantId, requestId);
    return erasure ?? reply.code(404).send({ error: 'erasure_request_not_found' });
  });

